changeSet.sql:
alter table mandant add constraint mandant_verwaltung_rollen_ck
    check (cardinality(verwaltung_rollen) > 0
        and verwaltung_rollen <@ array['inhaber', 'mitarbeiter', 'treuhaender', 'geschaeftsstelle']::text[]);
update mandant set verwaltung_rollen = array['geschaeftsstelle']::text[] where code = 'vhf-gsk';
